-- Generated by build_river.py. RGB24 plus all ten mip levels.
function MakeRiverDisplayTexture()
    local U=CS.UnityEngine
    local alphabet='ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/'
    local palette='ESYrEictEyguFCkvFSowFSsxFiwyFy0zGC40GS81GjA2GzE3GzI5HDM6HTQ7HjU8HzY9IDc+IDg/ITpAIjtBIzxCJD1DJT5FJj9GJkBHJ0FIKEJJKUNKKkRLK0VMLEZNLEdOLUhPLklRL0pSMEtTMUxUMk5VMk9WM1BXNFFYNVJZNlNaN1RbN1VdOFZeOVdfOlhgO1lhPFpiPVtjPVxkPl1lP15mQF9nQWBpQmFqQmJrQ2RsRGVtRWZuRmdvR2hw'
    local lut={}
    for i=1,#alphabet do lut[alphabet:sub(i,i)]=palette:sub(4*i-3,4*i) end
    local levels=''
    local packed=levels:gsub(".",lut)
    local bytes=CS.System.Convert.FromBase64String(packed)
    local tex=U.Texture2D(512,512,U.TextureFormat.RGB24,true)
    tex:LoadRawTextureData(bytes)
    tex:Apply(false,true)
    tex.name="River fine colour"
    return tex
end
